use crate::ipc::Router;

pub fn register_all(router: &mut Router) {
    window::register(router);
    analytics::register(router);
    settings::register(router);
    auth::register(router);
    friends::register(router);
    users::register(router);
    discovery::register(router);
    games::register(router);
    game_lists::register(router);
    catalog::register(router);
    chat::register(router);
    user_settings::register(router);
    instances::register(router);
    versions::register(router);
    launch::register(router);
    launch::register_running(router);
    app::register(router);
    protocol::register(router);
    inventory::register(router);
    trade_links::register(router);
    preferences::register(router);
    feeds::register(router);
    communities::register(router);
    thumbnails::register(router);
    social::register(router);
    feature_flags::register(router);
    metadata::register(router);
    updater::register(router);
    agreements::register(router);
}
